const hex = s => [1, 3, 5].map(i => parseInt(s.slice(i, i + 2), 16));

function mean(d, width, x, y, size = 5) {
  const sum = [0, 0, 0];
  for (let j = -size; j <= size; j++) for (let i = -size; i <= size; i++) {
    const k = ((y + j) * width + x + i) * 4;
