  const [wx, wy] = center('chapel', 'window'), [rx, ry] = center('chapel', 'rose');
  const list = [
    ['牛皮纸外框', 12, 12, C.kraft], ['牛皮纸下框', 960, 1072, C.kraft], ['天空', 800, 120, C.sky], ['太阳', 1590, 232, C.sun],
    ['头发', hx, hy, C.hair], ['外套（背缝一侧）', cx + 25, cy, C.coat], ['手中喜帖', hix, hiy, C.red],
